mkitem!{mkstruct!{# [doc = " A measurement of a monotonically nondecreasing clock."] # [doc = " Opaque and useful only with [`Duration`]."] # [doc = ""] # [doc = " Instants are always guaranteed, barring [platform bugs], to be no less than any previously"] # [doc = " measured instant when created, and are often useful for tasks such as measuring"] # [doc = " benchmarks or timing how long an operation takes."] # [doc = ""] # [doc = " Note, however, that instants are **not** guaranteed to be **steady**. In other"] # [doc = " words, each tick of the underlying clock might not be the same length (e.g."] # [doc = " some seconds may be longer than others). An instant may jump forwards or"] # [doc = " experience time dilation (slow down or speed up), but it will never go"] # [doc = " backwards."] # [doc = " As part of this non-guarantee it is also not specified whether system suspends count as"] # [doc = " elapsed time or not. The behavior varies across platforms and Rust versions."] # [doc = ""] # [doc = " Instants are opaque types that can only be compared to one another. There is"] # [doc = " no method to get \"the number of seconds\" from an instant. Instead, it only"] # [doc = " allows measuring the duration between two instants (or comparing two"] # [doc = " instants)."] # [doc = ""] # [doc = " The size of an `Instant` struct may vary depending on the target operating"] # [doc = " system."] # [doc = ""] # [doc = " Example:"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::time::{Duration, Instant};"] # [doc = " use std::thread::sleep;"] # [doc = ""] # [doc = " fn main() {"] # [doc = "    let now = Instant::now();"] # [doc = ""] # [doc = "    // we sleep for 2 seconds"] # [doc = "    sleep(Duration::new(2, 0));"] # [doc = "    // it prints '2'"] # [doc = "    println!(\"{}\", now.elapsed().as_secs());"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " [platform bugs]: Instant#monotonicity"] # [doc = ""] # [doc = " # OS-specific behaviors"] # [doc = ""] # [doc = " An `Instant` is a wrapper around system-specific types and it may behave"] # [doc = " differently depending on the underlying operating system. For example,"] # [doc = " the following snippet is fine on Linux but panics on macOS:"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::time::{Instant, Duration};"] # [doc = ""] # [doc = " let now = Instant::now();"] # [doc = " let days_per_10_millennia = 365_2425;"] # [doc = " let solar_seconds_per_day = 60 * 60 * 24;"] # [doc = " let millennium_in_solar_seconds = 31_556_952_000;"] # [doc = " assert_eq!(millennium_in_solar_seconds, days_per_10_millennia * solar_seconds_per_day / 10);"] # [doc = ""] # [doc = " let duration = Duration::new(millennium_in_solar_seconds, 0);"] # [doc = " println!(\"{:?}\", now + duration);"] # [doc = " ```"] # [doc = ""] # [doc = " For cross-platform code, you can comfortably use durations of up to around one hundred years."] # [doc = ""] # [doc = " # Underlying System calls"] # [doc = ""] # [doc = " The following system calls are [currently] being used by `now()` to find out"] # [doc = " the current time:"] # [doc = ""] # [doc = " |  Platform |               System call                                            |"] # [doc = " |-----------|----------------------------------------------------------------------|"] # [doc = " | SGX       | [`insecure_time` usercall]. More information on [timekeeping in SGX] |"] # [doc = " | UNIX      | [clock_gettime (Monotonic Clock)]                                    |"] # [doc = " | Darwin    | [clock_gettime (Monotonic Clock)]                                    |"] # [doc = " | VXWorks   | [clock_gettime (Monotonic Clock)]                                    |"] # [doc = " | SOLID     | `get_tim`                                                            |"] # [doc = " | WASI      | [__wasi_clock_time_get (Monotonic Clock)]                            |"] # [doc = " | Windows   | [QueryPerformanceCounter]                                            |"] # [doc = ""] # [doc = " [currently]: crate::io#platform-specific-behavior"] # [doc = " [QueryPerformanceCounter]: https://docs.microsoft.com/en-us/windows/win32/api/profileapi/nf-profileapi-queryperformancecounter"] # [doc = " [`insecure_time` usercall]: https://edp.fortanix.com/docs/api/fortanix_sgx_abi/struct.Usercalls.html#method.insecure_time"] # [doc = " [timekeeping in SGX]: https://edp.fortanix.com/docs/concepts/rust-std/#codestdtimecode"] # [doc = " [__wasi_clock_time_get (Monotonic Clock)]: https://github.com/WebAssembly/WASI/blob/main/legacy/preview1/docs.md#clock_time_get"] # [doc = " [clock_gettime (Monotonic Clock)]: https://linux.die.net/man/3/clock_gettime"] # [doc = ""] # [doc = " **Disclaimer:** These system calls might change over time."] # [doc = ""] # [doc = " > Note: mathematical operations like [`add`] may panic if the underlying"] # [doc = " > structure cannot represent the new point in time."] # [doc = ""] # [doc = " [`add`]: Instant::add"] # [doc = ""] # [doc = " ## Monotonicity"] # [doc = ""] # [doc = " On all platforms `Instant` will try to use an OS API that guarantees monotonic behavior"] # [doc = " if available, which is the case for all [tier 1] platforms."] # [doc = " In practice such guarantees are – under rare circumstances – broken by hardware, virtualization"] # [doc = " or operating system bugs. To work around these bugs and platforms not offering monotonic clocks"] # [doc = " [`duration_since`], [`elapsed`] and [`sub`] saturate to zero. In older Rust versions this"] # [doc = " lead to a panic instead. [`checked_duration_since`] can be used to detect and handle situations"] # [doc = " where monotonicity is violated, or `Instant`s are subtracted in the wrong order."] # [doc = ""] # [doc = " This workaround obscures programming errors where earlier and later instants are accidentally"] # [doc = " swapped. For this reason future Rust versions may reintroduce panics."] # [doc = ""] # [doc = " [tier 1]: https://doc.rust-lang.org/rustc/platform-support.html"] # [doc = " [`duration_since`]: Instant::duration_since"] # [doc = " [`elapsed`]: Instant::elapsed"] # [doc = " [`sub`]: Instant::sub"] # [doc = " [`checked_duration_since`]: Instant::checked_duration_since"] # [doc = ""] # [derive (Copy , Clone , PartialEq , Eq , PartialOrd , Ord , Hash)] # [stable (feature = "time2" , since = "1.8.0")] # [cfg_attr (not (test) , rustc_diagnostic_item = "Instant")] pub struct Instant (time :: Instant) ;}}
mkitem!{mkstruct!{# [doc = " A measurement of the system clock, useful for talking to"] # [doc = " external entities like the file system or other processes."] # [doc = ""] # [doc = " Distinct from the [`Instant`] type, this time measurement **is not"] # [doc = " monotonic**. This means that you can save a file to the file system, then"] # [doc = " save another file to the file system, **and the second file has a"] # [doc = " `SystemTime` measurement earlier than the first**. In other words, an"] # [doc = " operation that happens after another operation in real time may have an"] # [doc = " earlier `SystemTime`!"] # [doc = ""] # [doc = " Consequently, comparing two `SystemTime` instances to learn about the"] # [doc = " duration between them returns a [`Result`] instead of an infallible [`Duration`]"] # [doc = " to indicate that this sort of time drift may happen and needs to be handled."] # [doc = ""] # [doc = " Although a `SystemTime` cannot be directly inspected, the [`UNIX_EPOCH`]"] # [doc = " constant is provided in this module as an anchor in time to learn"] # [doc = " information about a `SystemTime`. By calculating the duration from this"] # [doc = " fixed point in time, a `SystemTime` can be converted to a human-readable time,"] # [doc = " or perhaps some other string representation."] # [doc = ""] # [doc = " The size of a `SystemTime` struct may vary depending on the target operating"] # [doc = " system."] # [doc = ""] # [doc = " A `SystemTime` does not count leap seconds."] # [doc = " `SystemTime::now()`'s behavior around a leap second"] # [doc = " is the same as the operating system's wall clock."] # [doc = " The precise behavior near a leap second"] # [doc = " (e.g. whether the clock appears to run slow or fast, or stop, or jump)"] # [doc = " depends on platform and configuration,"] # [doc = " so should not be relied on."] # [doc = ""] # [doc = " Example:"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::time::{Duration, SystemTime};"] # [doc = " use std::thread::sleep;"] # [doc = ""] # [doc = " fn main() {"] # [doc = "    let now = SystemTime::now();"] # [doc = ""] # [doc = "    // we sleep for 2 seconds"] # [doc = "    sleep(Duration::new(2, 0));"] # [doc = "    match now.elapsed() {"] # [doc = "        Ok(elapsed) => {"] # [doc = "            // it prints '2'"] # [doc = "            println!(\"{}\", elapsed.as_secs());"] # [doc = "        }"] # [doc = "        Err(e) => {"] # [doc = "            // the system clock went backwards!"] # [doc = "            println!(\"Great Scott! {e:?}\");"] # [doc = "        }"] # [doc = "    }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " # Platform-specific behavior"] # [doc = ""] # [doc = " The precision of `SystemTime` can depend on the underlying OS-specific time format."] # [doc = " For example, on Windows the time is represented in 100 nanosecond intervals whereas Linux"] # [doc = " can represent nanosecond intervals."] # [doc = ""] # [doc = " The following system calls are [currently] being used by `now()` to find out"] # [doc = " the current time:"] # [doc = ""] # [doc = " |  Platform |               System call                                            |"] # [doc = " |-----------|----------------------------------------------------------------------|"] # [doc = " | SGX       | [`insecure_time` usercall]. More information on [timekeeping in SGX] |"] # [doc = " | UNIX      | [clock_gettime (Realtime Clock)]                                     |"] # [doc = " | Darwin    | [clock_gettime (Realtime Clock)]                                     |"] # [doc = " | VXWorks   | [clock_gettime (Realtime Clock)]                                     |"] # [doc = " | SOLID     | `SOLID_RTC_ReadTime`                                                 |"] # [doc = " | WASI      | [__wasi_clock_time_get (Realtime Clock)]                             |"] # [doc = " | Windows   | [GetSystemTimePreciseAsFileTime] / [GetSystemTimeAsFileTime]         |"] # [doc = ""] # [doc = " [currently]: crate::io#platform-specific-behavior"] # [doc = " [`insecure_time` usercall]: https://edp.fortanix.com/docs/api/fortanix_sgx_abi/struct.Usercalls.html#method.insecure_time"] # [doc = " [timekeeping in SGX]: https://edp.fortanix.com/docs/concepts/rust-std/#codestdtimecode"] # [doc = " [clock_gettime (Realtime Clock)]: https://linux.die.net/man/3/clock_gettime"] # [doc = " [__wasi_clock_time_get (Realtime Clock)]: https://github.com/WebAssembly/WASI/blob/main/legacy/preview1/docs.md#clock_time_get"] # [doc = " [GetSystemTimePreciseAsFileTime]: https://docs.microsoft.com/en-us/windows/win32/api/sysinfoapi/nf-sysinfoapi-getsystemtimepreciseasfiletime"] # [doc = " [GetSystemTimeAsFileTime]: https://docs.microsoft.com/en-us/windows/win32/api/sysinfoapi/nf-sysinfoapi-getsystemtimeasfiletime"] # [doc = ""] # [doc = " **Disclaimer:** These system calls might change over time."] # [doc = ""] # [doc = " > Note: mathematical operations like [`add`] may panic if the underlying"] # [doc = " > structure cannot represent the new point in time."] # [doc = ""] # [doc = " [`add`]: SystemTime::add"] # [doc = " [`UNIX_EPOCH`]: SystemTime::UNIX_EPOCH"] # [derive (Copy , Clone , PartialEq , Eq , PartialOrd , Ord , Hash)] # [stable (feature = "time2" , since = "1.8.0")] pub struct SystemTime (time :: SystemTime) ;}}
mkitem!{mkstruct!{# [doc = " An error returned from the `duration_since` and `elapsed` methods on"] # [doc = " `SystemTime`, used to learn how far in the opposite direction a system time"] # [doc = " lies."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::thread::sleep;"] # [doc = " use std::time::{Duration, SystemTime};"] # [doc = ""] # [doc = " let sys_time = SystemTime::now();"] # [doc = " sleep(Duration::from_secs(1));"] # [doc = " let new_sys_time = SystemTime::now();"] # [doc = " match sys_time.duration_since(new_sys_time) {"] # [doc = "     Ok(_) => {}"] # [doc = "     Err(e) => println!(\"SystemTimeError difference: {:?}\", e.duration()),"] # [doc = " }"] # [doc = " ```"] # [derive (Clone , Debug)] # [stable (feature = "time2" , since = "1.8.0")] pub struct SystemTimeError (Duration) ;}}
mkitem!{mkimpl!{impl Instant { # [doc = " Returns an instant corresponding to \"now\"."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::time::Instant;"] # [doc = ""] # [doc = " let now = Instant::now();"] # [doc = " ```"] # [must_use] # [stable (feature = "time2" , since = "1.8.0")] # [cfg_attr (not (test) , rustc_diagnostic_item = "instant_now")] pub fn now () -> Instant { Instant (time :: Instant :: now ()) } # [doc = " Returns the amount of time elapsed from another instant to this one,"] # [doc = " or zero duration if that instant is later than this one."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Previous Rust versions panicked when `earlier` was later than `self`. Currently this"] # [doc = " method saturates. Future versions may reintroduce the panic in some circumstances."] # [doc = " See [Monotonicity]."] # [doc = ""] # [doc = " [Monotonicity]: Instant#monotonicity"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::time::{Duration, Instant};"] # [doc = " use std::thread::sleep;"] # [doc = ""] # [doc = " let now = Instant::now();"] # [doc = " sleep(Duration::new(1, 0));"] # [doc = " let new_now = Instant::now();"] # [doc = " println!(\"{:?}\", new_now.duration_since(now));"] # [doc = " println!(\"{:?}\", now.duration_since(new_now)); // 0ns"] # [doc = " ```"] # [must_use] # [stable (feature = "time2" , since = "1.8.0")] pub fn duration_since (& self , earlier : Instant) -> Duration { self . checked_duration_since (earlier) . unwrap_or_default () } # [doc = " Returns the amount of time elapsed from another instant to this one,"] # [doc = " or None if that instant is later than this one."] # [doc = ""] # [doc = " Due to [monotonicity bugs], even under correct logical ordering of the passed `Instant`s,"] # [doc = " this method can return `None`."] # [doc = ""] # [doc = " [monotonicity bugs]: Instant#monotonicity"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::time::{Duration, Instant};"] # [doc = " use std::thread::sleep;"] # [doc = ""] # [doc = " let now = Instant::now();"] # [doc = " sleep(Duration::new(1, 0));"] # [doc = " let new_now = Instant::now();"] # [doc = " println!(\"{:?}\", new_now.checked_duration_since(now));"] # [doc = " println!(\"{:?}\", now.checked_duration_since(new_now)); // None"] # [doc = " ```"] # [must_use] # [stable (feature = "checked_duration_since" , since = "1.39.0")] pub fn checked_duration_since (& self , earlier : Instant) -> Option < Duration > { self . 0 . checked_sub_instant (& earlier . 0) } # [doc = " Returns the amount of time elapsed from another instant to this one,"] # [doc = " or zero duration if that instant is later than this one."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::time::{Duration, Instant};"] # [doc = " use std::thread::sleep;"] # [doc = ""] # [doc = " let now = Instant::now();"] # [doc = " sleep(Duration::new(1, 0));"] # [doc = " let new_now = Instant::now();"] # [doc = " println!(\"{:?}\", new_now.saturating_duration_since(now));"] # [doc = " println!(\"{:?}\", now.saturating_duration_since(new_now)); // 0ns"] # [doc = " ```"] # [must_use] # [stable (feature = "checked_duration_since" , since = "1.39.0")] pub fn saturating_duration_since (& self , earlier : Instant) -> Duration { self . checked_duration_since (earlier) . unwrap_or_default () } # [doc = " Returns the amount of time elapsed since this instant."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Previous Rust versions panicked when the current time was earlier than self. Currently this"] # [doc = " method returns a Duration of zero in that case. Future versions may reintroduce the panic."] # [doc = " See [Monotonicity]."] # [doc = ""] # [doc = " [Monotonicity]: Instant#monotonicity"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::thread::sleep;"] # [doc = " use std::time::{Duration, Instant};"] # [doc = ""] # [doc = " let instant = Instant::now();"] # [doc = " let three_secs = Duration::from_secs(3);"] # [doc = " sleep(three_secs);"] # [doc = " assert!(instant.elapsed() >= three_secs);"] # [doc = " ```"] # [must_use] # [stable (feature = "time2" , since = "1.8.0")] pub fn elapsed (& self) -> Duration { Instant :: now () - * self } # [doc = " Returns `Some(t)` where `t` is the time `self + duration` if `t` can be represented as"] # [doc = " `Instant` (which means it's inside the bounds of the underlying data structure), `None`"] # [doc = " otherwise."] # [stable (feature = "time_checked_add" , since = "1.34.0")] pub fn checked_add (& self , duration : Duration) -> Option < Instant > { self . 0 . checked_add_duration (& duration) . map (Instant) } # [doc = " Returns `Some(t)` where `t` is the time `self - duration` if `t` can be represented as"] # [doc = " `Instant` (which means it's inside the bounds of the underlying data structure), `None`"] # [doc = " otherwise."] # [stable (feature = "time_checked_add" , since = "1.34.0")] pub fn checked_sub (& self , duration : Duration) -> Option < Instant > { self . 0 . checked_sub_duration (& duration) . map (Instant) } # [cfg_attr (not (target_os = "linux") , allow (unused , reason = "not every platform has a specific `sleep_until`"))] pub (crate) fn into_inner (self) -> time :: Instant { self . 0 } }}}
mkitem!{mkimpl!{# [stable (feature = "time2" , since = "1.8.0")] impl Add < Duration > for Instant { type Output = Instant ; # [doc = " # Panics"] # [doc = ""] # [doc = " This function may panic if the resulting point in time cannot be represented by the"] # [doc = " underlying data structure. See [`Instant::checked_add`] for a version without panic."] fn add (self , other : Duration) -> Instant { self . checked_add (other) . expect ("overflow when adding duration to instant") } }}}
mkitem!{mkimpl!{# [stable (feature = "time_augmented_assignment" , since = "1.9.0")] impl AddAssign < Duration > for Instant { fn add_assign (& mut self , other : Duration) { * self = * self + other ; } }}}
mkitem!{mkimpl!{# [stable (feature = "time2" , since = "1.8.0")] impl Sub < Duration > for Instant { type Output = Instant ; fn sub (self , other : Duration) -> Instant { self . checked_sub (other) . expect ("overflow when subtracting duration from instant") } }}}
mkitem!{mkimpl!{# [stable (feature = "time_augmented_assignment" , since = "1.9.0")] impl SubAssign < Duration > for Instant { fn sub_assign (& mut self , other : Duration) { * self = * self - other ; } }}}
mkitem!{mkimpl!{# [stable (feature = "time2" , since = "1.8.0")] impl Sub < Instant > for Instant { type Output = Duration ; # [doc = " Returns the amount of time elapsed from another instant to this one,"] # [doc = " or zero duration if that instant is later than this one."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Previous Rust versions panicked when `other` was later than `self`. Currently this"] # [doc = " method saturates. Future versions may reintroduce the panic in some circumstances."] # [doc = " See [Monotonicity]."] # [doc = ""] # [doc = " [Monotonicity]: Instant#monotonicity"] fn sub (self , other : Instant) -> Duration { self . duration_since (other) } }}}
mkitem!{mkimpl!{# [stable (feature = "time2" , since = "1.8.0")] impl fmt :: Debug for Instant { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { self . 0 . fmt (f) } }}}
mkitem!{mkimpl!{impl SystemTime { # [doc = " An anchor in time which can be used to create new `SystemTime` instances or"] # [doc = " learn about where in time a `SystemTime` lies."] # [doc = ""] # [doc = " This constant is defined to be \"1970-01-01 00:00:00 UTC\" on all systems with"] # [doc = " respect to the system clock. Using `duration_since` on an existing"] # [doc = " `SystemTime` instance can tell how far away from this point in time a"] # [doc = " measurement lies, and using `UNIX_EPOCH + duration` can be used to create a"] # [doc = " `SystemTime` instance to represent another fixed point in time."] # [doc = ""] # [doc = " `duration_since(UNIX_EPOCH).unwrap().as_secs()` returns"] # [doc = " the number of non-leap seconds since the start of 1970 UTC."] # [doc = " This is a POSIX `time_t` (as a `u64`),"] # [doc = " and is the same time representation as used in many Internet protocols."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::time::SystemTime;"] # [doc = ""] # [doc = " match SystemTime::now().duration_since(SystemTime::UNIX_EPOCH) {"] # [doc = "     Ok(n) => println!(\"1970-01-01 00:00:00 UTC was {} seconds ago!\", n.as_secs()),"] # [doc = "     Err(_) => panic!(\"SystemTime before UNIX EPOCH!\"),"] # [doc = " }"] # [doc = " ```"] # [stable (feature = "assoc_unix_epoch" , since = "1.28.0")] pub const UNIX_EPOCH : SystemTime = UNIX_EPOCH ; # [doc = " Returns the system time corresponding to \"now\"."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::time::SystemTime;"] # [doc = ""] # [doc = " let sys_time = SystemTime::now();"] # [doc = " ```"] # [must_use] # [stable (feature = "time2" , since = "1.8.0")] pub fn now () -> SystemTime { SystemTime (time :: SystemTime :: now ()) } # [doc = " Returns the amount of time elapsed from an earlier point in time."] # [doc = ""] # [doc = " This function may fail because measurements taken earlier are not"] # [doc = " guaranteed to always be before later measurements (due to anomalies such"] # [doc = " as the system clock being adjusted either forwards or backwards)."] # [doc = " [`Instant`] can be used to measure elapsed time without this risk of failure."] # [doc = ""] # [doc = " If successful, <code>[Ok]\\([Duration])</code> is returned where the duration represents"] # [doc = " the amount of time elapsed from the specified measurement to this one."] # [doc = ""] # [doc = " Returns an [`Err`] if `earlier` is later than `self`, and the error"] # [doc = " contains how far from `self` the time is."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::time::SystemTime;"] # [doc = ""] # [doc = " let sys_time = SystemTime::now();"] # [doc = " let new_sys_time = SystemTime::now();"] # [doc = " let difference = new_sys_time.duration_since(sys_time)"] # [doc = "     .expect(\"Clock may have gone backwards\");"] # [doc = " println!(\"{difference:?}\");"] # [doc = " ```"] # [stable (feature = "time2" , since = "1.8.0")] pub fn duration_since (& self , earlier : SystemTime) -> Result < Duration , SystemTimeError > { self . 0 . sub_time (& earlier . 0) . map_err (SystemTimeError) } # [doc = " Returns the difference from this system time to the"] # [doc = " current clock time."] # [doc = ""] # [doc = " This function may fail as the underlying system clock is susceptible to"] # [doc = " drift and updates (e.g., the system clock could go backwards), so this"] # [doc = " function might not always succeed. If successful, <code>[Ok]\\([Duration])</code> is"] # [doc = " returned where the duration represents the amount of time elapsed from"] # [doc = " this time measurement to the current time."] # [doc = ""] # [doc = " To measure elapsed time reliably, use [`Instant`] instead."] # [doc = ""] # [doc = " Returns an [`Err`] if `self` is later than the current system time, and"] # [doc = " the error contains how far from the current system time `self` is."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::thread::sleep;"] # [doc = " use std::time::{Duration, SystemTime};"] # [doc = ""] # [doc = " let sys_time = SystemTime::now();"] # [doc = " let one_sec = Duration::from_secs(1);"] # [doc = " sleep(one_sec);"] # [doc = " assert!(sys_time.elapsed().unwrap() >= one_sec);"] # [doc = " ```"] # [stable (feature = "time2" , since = "1.8.0")] pub fn elapsed (& self) -> Result < Duration , SystemTimeError > { SystemTime :: now () . duration_since (* self) } # [doc = " Returns `Some(t)` where `t` is the time `self + duration` if `t` can be represented as"] # [doc = " `SystemTime` (which means it's inside the bounds of the underlying data structure), `None`"] # [doc = " otherwise."] # [stable (feature = "time_checked_add" , since = "1.34.0")] pub fn checked_add (& self , duration : Duration) -> Option < SystemTime > { self . 0 . checked_add_duration (& duration) . map (SystemTime) } # [doc = " Returns `Some(t)` where `t` is the time `self - duration` if `t` can be represented as"] # [doc = " `SystemTime` (which means it's inside the bounds of the underlying data structure), `None`"] # [doc = " otherwise."] # [stable (feature = "time_checked_add" , since = "1.34.0")] pub fn checked_sub (& self , duration : Duration) -> Option < SystemTime > { self . 0 . checked_sub_duration (& duration) . map (SystemTime) } }}}
